// Deliver after 50ms of silence (debounce)
const settle = createDeliveryStrategy<Tick>(({ deliver }) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let last: DeliveryMessageType<Tick> | undefined;
  return {
    push: (message) => {
      last = message;
      clearTimeout(timer);
      timer = setTimeout(() => {
        if (last) deliver(last);
        last = undefined;
      }, 50);
    },
    dispose: () => {
      clearTimeout(timer);
      last = undefined;
    },
  };
});
